package app.murmur.audio

import java.util.Random
import kotlin.math.PI
import kotlin.math.exp
import kotlin.math.sin

/** Background sounds. All are generated by the app itself: no audio files, and no music. */
enum class AmbienceKind(val label: String) {
    NONE("Off"),
    RAIN("Rain"),
    STORM("Thunderstorm"),
    WIND("Wind"),
    OCEAN("Ocean"),
    STREAM("Stream"),
    FOREST("Forest birds"),
    NIGHT("Night crickets"),
    FIRE("Campfire"),
    DESERT("Desert wind"),
    CAVE("Cave drips"),
    HEARTBEAT("Heartbeat"),
    CALM("Deep calm"),
}

fun interface SoundGen {
    /** Next mono sample, roughly in -1..1. */
    fun next(): Float
}

object Generators {
    const val RATE = 22050

    fun create(kind: AmbienceKind, rnd: Random = Random()): SoundGen = when (kind) {
        AmbienceKind.RAIN -> RainGen(rnd, heavy = false)
        AmbienceKind.STORM -> StormGen(rnd)
        AmbienceKind.WIND -> WindGen(rnd)
        AmbienceKind.OCEAN -> OceanGen(rnd)
        AmbienceKind.STREAM -> StreamGen(rnd)
        AmbienceKind.FOREST -> ForestGen(rnd)
        AmbienceKind.NIGHT -> NightGen(rnd)
        AmbienceKind.FIRE -> FireGen(rnd)
        AmbienceKind.DESERT -> DesertGen(rnd)
        AmbienceKind.CAVE -> CaveGen(rnd)
        AmbienceKind.HEARTBEAT -> HeartbeatGen(rnd)
        AmbienceKind.CALM -> CalmGen(rnd)
        AmbienceKind.NONE -> SoundGen { 0f }
    }
}

private fun white(rnd: Random) = rnd.nextFloat() * 2f - 1f

private class RainGen(private val rnd: Random, private val heavy: Boolean) : SoundGen {
    private var lp = 0f
    private var drop = 0f
    override fun next(): Float {
        val w = white(rnd)
        lp += 0.25f * (w - lp)
        if (rnd.nextFloat() < (if (heavy) 0.0014f else 0.0006f)) drop = 0.8f
        drop *= 0.995f
        return (w - lp) * (if (heavy) 0.8f else 0.55f) + drop * w * 0.5f
    }
}

/** Heavy rain with distant thunder rolling in every 6-18 seconds. */
private class StormGen(private val rnd: Random) : SoundGen {
    private val rain = RainGen(rnd, heavy = true)
    private var brown = 0f
    private var phase = 0
    private var env = 0f
    private var wait = nextWait()
    private fun nextWait() = ((6 + rnd.nextFloat() * 12) * Generators.RATE).toInt()
    override fun next(): Float {
        val w = white(rnd)
        brown = (brown + 0.02f * w) / 1.02f
        when (phase) {
            0 -> if (--wait <= 0) phase = 1
            1 -> { env += 1f / (0.7f * Generators.RATE); if (env >= 1f) { env = 1f; phase = 2 } }
            else -> { env *= 0.999991f; if (env < 0.01f) { env = 0f; phase = 0; wait = nextWait() } }
        }
        return rain.next() * 0.85f + brown * 3.5f * env * 1.4f
    }
}

private class WindGen(private val rnd: Random) : SoundGen {
    private var brown = 0f
    private var smooth = 0f
    private var t = 0.0
    override fun next(): Float {
        t += 1.0 / Generators.RATE
        brown = (brown + 0.02f * white(rnd)) / 1.02f
        smooth += 0.05f * (brown * 3.5f - smooth)
        val lfo = 0.55f + 0.45f * sin(2 * PI * 0.07 * t).toFloat()
        return smooth * lfo * 1.8f
    }
}

private class OceanGen(private val rnd: Random) : SoundGen {
    private var brown = 0f
    private var t = 0.0
    override fun next(): Float {
        t += 1.0 / Generators.RATE
        brown = (brown + 0.02f * white(rnd)) / 1.02f
        val swell = 0.5f + 0.5f * sin(2 * PI * 0.09 * t).toFloat()
        return brown * 3.5f * (0.25f + 0.75f * swell * swell) * 1.3f
    }
}

/** Bubbling water: mid-band noise with random amplitude wobble. */
private class StreamGen(private val rnd: Random) : SoundGen {
    private var y1 = 0f
    private var y2 = 0f
    private var count = 0
    private val mod = FloatArray(3)
    override fun next(): Float {
        val w = white(rnd)
        y1 += 0.35f * (w - y1)
        y2 += 0.06f * (y1 - y2)
        if (++count >= 220) {
            count = 0
            for (k in mod.indices) mod[k] += 0.4f * (rnd.nextFloat() - mod[k])
        }
        val m = 0.5f + (mod[0] + mod[1] + mod[2]) / 3f
        return (y1 - y2) * m * 2.4f
    }
}

private class BirdGen(private val rnd: Random) : SoundGen {
    private var wait = Generators.RATE
    private var notesLeft = 0
    private var noteLeft = 0
    private var noteTotal = 1
    private var gap = 0
    private var f0 = 3000f
    private var f = 3000f
    private var slope = 0f
    private var phase = 0.0

    private fun startNote() {
        notesLeft--
        noteTotal = ((0.06 + rnd.nextFloat() * 0.09) * Generators.RATE).toInt().coerceAtLeast(1)
        noteLeft = noteTotal
        f = f0 * (0.9f + rnd.nextFloat() * 0.3f)
        slope = (rnd.nextFloat() - 0.5f) * 0.8f
    }

    override fun next(): Float {
        var out = 0f
        if (noteLeft > 0) {
            val prog = 1f - noteLeft.toFloat() / noteTotal
            val env = sin(PI * prog).toFloat()
            f += slope
            phase += 2 * PI * f / Generators.RATE
            out = (sin(phase) * env * 0.22).toFloat()
            noteLeft--
            if (noteLeft == 0 && notesLeft > 0) gap = (0.05 * Generators.RATE).toInt()
        } else if (gap > 0) {
            gap--
            if (gap == 0 && notesLeft > 0) startNote()
        } else if (--wait <= 0) {
            notesLeft = 2 + rnd.nextInt(4)
            f0 = 2200f + rnd.nextFloat() * 2000f
            startNote()
            wait = ((1.5 + rnd.nextFloat() * 4.5) * Generators.RATE).toInt()
        }
        return out
    }
}

private class ForestGen(rnd: Random) : SoundGen {
    private val wind = WindGen(rnd)
    private val birds = BirdGen(rnd)
    override fun next(): Float = wind.next() * 0.35f + birds.next()
}

/** Crickets: two gated high-pitched carriers in slow bursts over a faint low bed. */
private class NightGen(private val rnd: Random) : SoundGen {
    private var t = 0.0
    private var bed = 0f
    private fun burst(rate: Double): Float {
        val x = (t * rate) % 1.0
        return if (x < 0.5) sin(PI * x / 0.5).toFloat() else 0f
    }
    override fun next(): Float {
        t += 1.0 / Generators.RATE
        bed = (bed + 0.02f * white(rnd)) / 1.02f
        val p1 = sin(2 * PI * 38 * t).toFloat().coerceAtLeast(0f)
        val p2 = sin(2 * PI * 33 * t).toFloat().coerceAtLeast(0f)
        val c1 = sin(2 * PI * 4300 * t).toFloat() * p1 * p1 * burst(2.9)
        val c2 = sin(2 * PI * 4700 * t).toFloat() * p2 * p2 * burst(2.3)
        return c1 * 0.10f + c2 * 0.08f + bed * 3.5f * 0.12f
    }
}

private class FireGen(private val rnd: Random) : SoundGen {
    private var brown = 0f
    private var lp = 0f
    private var crack = 0f
    override fun next(): Float {
        val w = white(rnd)
        brown = (brown + 0.02f * w) / 1.02f
        lp += 0.15f * (w - lp)
        if (rnd.nextFloat() < 0.0035f) crack = 0.5f + rnd.nextFloat() * 0.5f
        if (rnd.nextFloat() < 0.0002f) crack = 1f
        crack *= 0.9985f
        return brown * 3.5f * 0.35f + lp * 0.12f + w * crack * 0.55f
    }
}

private class DesertGen(private val rnd: Random) : SoundGen {
    private var lp = 0f
    private var t = 0.0
    override fun next(): Float {
        t += 1.0 / Generators.RATE
        lp += 0.06f * (white(rnd) - lp)
        val lfo = 0.5f + 0.5f * sin(2 * PI * 0.045 * t).toFloat()
        return lp * (0.25f + 0.9f * lfo * lfo) * 2.4f
    }
}

/** Low rumble with occasional water drips and a short echo. */
private class CaveGen(private val rnd: Random) : SoundGen {
    private var brown = 0f
    private var wait = Generators.RATE
    private var dripEnv = 0f
    private var dripPhase = 0.0
    private var dripF = 1100f
    private val echo = FloatArray((0.28 * Generators.RATE).toInt())
    private var pos = 0
    override fun next(): Float {
        brown = (brown + 0.02f * white(rnd)) / 1.02f
        if (--wait <= 0) {
            dripEnv = 0.9f
            dripF = 900f + rnd.nextFloat() * 700f
            wait = ((1.2 + rnd.nextFloat() * 4.0) * Generators.RATE).toInt()
        }
        dripPhase += 2 * PI * dripF / Generators.RATE
        dripF *= 0.99997f
        val d = (sin(dripPhase) * dripEnv).toFloat()
        dripEnv *= 0.9993f
        val delayed = echo[pos]
        echo[pos] = d + delayed * 0.35f
        pos = (pos + 1) % echo.size
        return brown * 3.5f * 0.28f + (d + delayed * 0.4f) * 0.35f
    }
}

/** A slow, low "lub-dub". A pulse, not a tone or melody. */
private class HeartbeatGen(private val rnd: Random) : SoundGen {
    private var t = 0.0
    private var brown = 0f
    private val period = 60.0 / 68.0
    private fun thump(x: Double, start: Double, amp: Float): Float {
        val d = x - start
        if (d < 0 || d > 0.25) return 0f
        val env = (1 - exp(-d * 90)) * exp(-d * 18)
        return (sin(2 * PI * 55 * d) * env * amp).toFloat()
    }
    override fun next(): Float {
        t += 1.0 / Generators.RATE
        brown = (brown + 0.02f * white(rnd)) / 1.02f
        val x = t % period
        return (thump(x, 0.0, 1.0f) + thump(x, 0.30, 0.7f)) * 1.4f + brown * 0.15f
    }
}

private class CalmGen(private val rnd: Random) : SoundGen {
    private var brown = 0f
    override fun next(): Float {
        brown = (brown + 0.02f * white(rnd)) / 1.02f
        return brown * 3.2f
    }
}
